use std::fs::File;
use std::path::Path;
use image::{DynamicImage, JpegEncoder};

fn save_compressed_jpeg(image: &DynamicImage, path_str: &str, quality: u8) -> Result<(), Box<dyn std::error::Error>> {
    // 1. Construct the destination path
    let dest_path = Path::new(path_str);

    // 2. Create the file
    let mut file_writer = File::create(dest_path)?;

    // 3. Create the JPEG encoder with the specified quality
    let encoder = JpegEncoder::new_with_quality(&mut file_writer, quality);

    // 4. Write the image to the file
    encoder
        .write_image(
            image.as_bytes(),
            image.width(),
            image.height(),
            image.color(),
        )?;

    Ok(())
}
```

